// ByState answers for a state identifier as protocol 775 carries one, which is
// an index into the game's block state registry.
//
// The exception is checked first because it is the whole reason this version is
// keyed by state. Every wall in the game is registered so that all of its states
// answer alike, except one, whose unconnected states have no collision shape and
// do not stop movement; a lookup that read only the range would say they do.
func (registry *blockMovementRegistry) ByState(state data.BlockStateID) (bool, bool) {
	if blocks, isException := registry.exceptions[state]; isException {
		return blocks, true
	}

	index := sort.Search(len(registry.ranges), func(i int) bool {
		return registry.ranges[i].to >= state
	})
	if index == len(registry.ranges) || registry.ranges[index].from > state {
		return false, false
	}

	return registry.ranges[index].blocks, true
}

// ByID answers for a whole block, and reports unknown for a block whose states
// do not agree.
//
// Refusing is the honest answer rather than a missing feature. One block in this
// version stops movement in most of its states and not in the rest, so there is
// no single fact about the block to report, and reporting the common case would
// be wrong for the others with nothing to signal it. A caller holding a state
// should ask ByState, which always has an answer.
func (registry *blockMovementRegistry) ByID(id data.BlockID) (bool, bool) {
	blocks, known := registry.byID[id]
	return blocks, known
}

// All returns the measurement keyed by block. It omits any block whose states
// disagree, for the reason ByID gives.
func (registry *blockMovementRegistry) All() data.BlockMovementIndex {
	return registry.byID.Clone()
}
